<script setup>
import {ref,computed,watch,onBeforeUnmount} from 'vue';
import {errorText,id} from './client.mjs';
import {contract} from './schema.mjs';
import Field from './Field.vue';
import Quantity from './Quantity.vue';
const props=defineProps({modelValue:Object,client:Object,base:Object,status:Object,saved:Boolean,readonly:Boolean,section:{type:String,default:'service'}});
const emit=defineEmits(['update:modelValue','pending','busy']);let alive=true;
const endpoint=ref(''),key=ref(''),busy=ref(false),error=ref(''),notice=ref(''),replaceKeys=ref(false),probe=ref(null),probing=ref(false),version=ref('default'),promptDraft=ref(props.modelValue.prompt);let probeEpoch=0,promptStart=null;
const set=(name,value)=>emit('update:modelValue',{...props.modelValue,[name]:value});
const configured=computed(()=>!!(props.modelValue.endpoint_ref&&props.modelValue.credential_refs.length&&props.modelValue.model));
const pending=computed(()=>!!(endpoint.value||key.value));watch(pending,v=>emit('pending',v));
const connectionState=computed(()=>busy.value?'正在写入连接信息':probing.value?'正在测试连接':error.value?'连接写入或测试未完成':probe.value?.state==='MODEL_RESPONDED'?'连接测试成功':probe.value?.state==='CACHED'?'已读取缓存 · 本次未发送请求':probe.value?'连接测试失败':pending.value?'连接信息尚未写入草稿':!configured.value?'尚未配置连接':!props.saved?'名称识别设置尚未保存':'连接已配置 · 尚未测试');
const versions=computed(()=>[
 ['default','默认提示词',contract.defaults.ai_assist.prompt],
 ['backup','最近备份',props.modelValue.prompt_backup],
 ['previous','更早备份',props.modelValue.prompt_previous_backup],
].filter(([,label,value])=>label==='默认提示词'||!!value));
const selectedVersion=computed(()=>versions.value.find(([name])=>name===version.value)?.[2]||contract.defaults.ai_assist.prompt);

async function testConnection(){if(probing.value||!props.saved||pending.value||props.status?.error.value)return;const epoch=++probeEpoch;probing.value=true;error.value='';probe.value=null;try{const result=await props.client.post('/ai/connection-test',{config_revision:props.status.current.value.revision,runtime_generation:props.status.health.value.generation});if(alive&&epoch===probeEpoch)probe.value=result}catch(e){if(alive&&epoch===probeEpoch)error.value=errorText(e)}finally{if(alive&&epoch===probeEpoch)probing.value=false}}
watch(()=>JSON.stringify([props.saved,props.modelValue]),()=>{probeEpoch++;probe.value=null;probing.value=false});
watch(()=>props.modelValue.prompt,value=>{if(value!==promptDraft.value)promptDraft.value=value});
watch(()=>props.saved,value=>{if(value)promptStart=null});
function editPrompt(value){if(promptStart===null)promptStart={prompt:props.modelValue.prompt,backup:props.modelValue.prompt_backup};promptDraft.value=value;emit('update:modelValue',{...props.modelValue,prompt:value,prompt_backup:promptStart.prompt,prompt_previous_backup:promptStart.backup})}
function restore(value){promptStart=null;promptDraft.value=value;emit('update:modelValue',{...props.modelValue,prompt:value,prompt_backup:props.modelValue.prompt,prompt_previous_backup:props.modelValue.prompt_backup});notice.value='已恢复到草稿；保存名称识别设置后生效。'}
async function storeCredentials(){if(busy.value||props.readonly||!pending.value||!props.base)return;busy.value=true;emit('busy',true);error.value='';notice.value='';let draft={...props.modelValue};try{for(const [kind,value] of [['endpoint',endpoint.value.trim()],['key',key.value.trim()]]){if(!value)continue;const result=await props.client.post('/credentials',{...props.base,operation_id:id(),kind,value});if(!alive)return;if(!/^secret:[a-f0-9]{32}$/.test(result.reference))throw Error('INVALID_CREDENTIAL_REFERENCE');draft=kind==='endpoint'?{...draft,endpoint_ref:result.reference}:{...draft,credential_refs:replaceKeys.value?[result.reference]:[...draft.credential_refs,result.reference]};emit('update:modelValue',draft);if(kind==='endpoint')endpoint.value='';else key.value=''}if(alive)notice.value='连接信息已写入本次草稿；请保存名称识别设置。'}catch(e){if(alive)error.value=errorText(e)+' 已成功写入的部分保留在草稿中。'}finally{key.value='';if(alive){busy.value=false;emit('busy',false)}}}
onBeforeUnmount(()=>{alive=false;endpoint.value='';key.value='';emit('pending',false);emit('busy',false)});
</script>

<template><section aria-label="AI 连接与名称辅助">
 <template v-if="section==='service'"><label class="sb-toggle-row"><span><strong>启用 AI 名称辅助</strong><small>仅辅助名称识别，不改变质量策略或执行权限。</small></span><input type="checkbox" :checked="modelValue.enabled" :disabled="readonly||busy" @change="set('enabled',$event.target.checked)"></label><section class="sb-form-section sb-form-narrow"><h4>AI 服务</h4><div class="sb-connection-state" role="status"><strong>{{connectionState}}</strong><small v-if="configured">{{modelValue.model}} · {{modelValue.credential_refs.length}} 份密钥</small></div><label>服务地址<input v-model="endpoint" type="password" autocomplete="off" maxlength="4096" :disabled="readonly||busy" :placeholder="modelValue.endpoint_ref?'地址已私密保存；留空保留':'输入 OpenAI 兼容服务地址'"><small>地址只写入私密存储，不回显历史值。</small></label><div class="sb-grid"><label>模型名称<input :value="modelValue.model" :disabled="readonly||busy" maxlength="256" placeholder="例如 deepseek-chat" @input="set('model',$event.target.value)"></label><label>接口兼容模式<select :value="modelValue.profile" :disabled="readonly||busy" @change="set('profile',$event.target.value)"><option value="auto">自动</option><option value="deepseek">DeepSeek</option><option value="generic">OpenAI 兼容接口</option></select></label></div><label>新密钥<input v-model="key" type="password" autocomplete="new-password" maxlength="4096" :disabled="readonly||busy" placeholder="输入后私密写入，不进入普通配置"></label><label v-if="modelValue.credential_refs.length" class="sb-check"><input v-model="replaceKeys" type="checkbox" :disabled="readonly||busy">用本次密钥替换当前轮换列表（默认追加到末尾）</label><div class="sb-actions"><VBtn variant="tonal" :disabled="readonly||busy||!pending||!base" @click="storeCredentials">{{busy?'正在写入…':'写入连接信息'}}</VBtn><VBtn variant="tonal" :disabled="!saved||!configured||pending||busy||probing||!!status?.error.value" @click="testConnection">{{probing?'正在测试…':'测试连接'}}</VBtn></div><p class="sb-muted">测试连接会发送一个固定影片标题，可能消耗模型额度；保存设置不会执行测试。</p><p v-if="notice" role="status">{{notice}}</p><p v-if="error" role="alert" class="sb-error">{{error}}</p><p v-if="probe" role="status">{{probe.state==='MODEL_RESPONDED'?'模型返回了有效识别结果。':probe.state==='CACHED'?'本次复用缓存，没有新发请求。':'未获得有效模型响应。'}}<template v-if="probe.result?.attempts!=null"> 请求 {{probe.result.attempts}} 次。</template></p><p v-if="probe?.result?.elapsed_ms!=null" class="sb-muted">响应耗时 {{probe.result.elapsed_ms}} ms。</p></section><section v-if="modelValue.credential_refs.length" class="sb-form-section sb-form-narrow"><h4>密钥使用顺序</h4><ol><li v-for="(credential,index) in modelValue.credential_refs" :key="credential">{{index===0?'首选密钥':'备用密钥 '+index}} <VBtn v-if="index>0" variant="text" :disabled="readonly||busy" @click="set('credential_refs',[credential,...modelValue.credential_refs.filter(c=>c!==credential)])">设为首选</VBtn><VBtn variant="text" color="error" :disabled="readonly||busy" @click="set('credential_refs',modelValue.credential_refs.filter(c=>c!==credential))">停止使用</VBtn></li></ol><p class="sb-muted">停止使用只移除配置引用，不删除私密存储中的历史值。</p></section><section class="sb-form-section"><h4>识别接口</h4><div class="sb-grid"><Field v-for="name in ['name_assistance_enabled','compatible','proxy','name_recognize_bridge']" :key="name" :name="name" :schema="contract.schemas.AIConfig.properties[name]" :model-value="modelValue[name]" :readonly="readonly||busy" @update:model-value="set(name,$event)"/></div></section></template>

 <section v-else-if="section==='prompt'" class="sb-form-section"><h4>提示词与版本</h4><label>当前提示词<textarea class="sb-prompt" rows="14" maxlength="32768" :value="promptDraft" :disabled="readonly||busy" @input="editPrompt($event.target.value)"></textarea></label><div class="sb-version-picker"><label>恢复版本<select v-model="version" :disabled="readonly||busy"><option v-for="[name,title] in versions" :key="name" :value="name">{{title}}</option></select></label><VBtn variant="tonal" :disabled="readonly||busy||selectedVersion===promptDraft" @click="restore(selectedVersion)">恢复到草稿</VBtn></div><p class="sb-muted">选择备份后恢复到上方核对；保存名称识别设置后生效。</p><p v-if="notice" role="status">{{notice}}</p></section>

 <section v-else-if="section==='limits'" class="sb-form-section"><h4>缓存与限流</h4><div class="sb-grid"><Field v-for="name in ['max_attempts','max_concurrency','queue_size','cache_size','notifications']" :key="name" :name="name" :schema="contract.schemas.AIConfig.properties[name]" :model-value="modelValue[name]" :readonly="readonly||busy" @update:model-value="set(name,$event)"/><Quantity v-for="[name,title] in [['timeout','模型请求超时'],['positive_ttl','成功识别缓存时间'],['negative_ttl','未识别结果缓存时间']]" :key="name" :label="title" :model-value="modelValue[name]" :readonly="readonly||busy" @update:model-value="set(name,$event)"/></div></section>
</section></template>
